  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*if the card password and id is validated,
   *and the input card exists and the input quantity greater or equal to 100, then the input card balance will plus the quantity
   *and the deposited number is equal to the deposited number.*/
  depositFunds(quantity: number): boolean {
    /*Definition Start*/
    let cards: BankCard[] = l({
      logic: () =>
        getRepository(BankCard).filter(
          (c: any) =>
            l({
              logic: () => c === this.InputCard,
              description: "c=self.InputCard",
            }).build().pass,
        ),
      description: "BankCard.allInstance()->select(c|c=self.InputCard)",
    }).build().pass;
    let isInputCardExists: boolean = l({
      logic: () => cards.length > 0,
      description: "cards.size()>0",
    }).build().pass;
    let isValidQuantity: boolean = l({
      logic: () => quantity >= 100,
      description: "quantity>=100",
    }).build().pass;
    let passwordIsValid: boolean = l({
      logic: () => this.PasswordValidated,
      description: "self.PasswordValidated",
    })
      .and({
        logic: () => this.CardIDValidated,
        description: "self.CardIDValidated",
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => passwordIsValid,
        description: "passwordIsValid",
      })
        .and({
          logic: () => isInputCardExists,
          description: "isInputCardExists",
        })
        .and({
          logic: () => isValidQuantity,
